customCss:
/* 全局变量定义 */
:root {
  --light-bg: #f8fafc;
  --dark-bg: #0f172a;
  --light-content-bg: rgba(255, 255, 255, 0.9);
  --dark-content-bg: rgba(15, 23, 42, 0.9);
}

/* 二次元背景图 - 适配明暗主题 */
[data-color-mode="light"] body {
  background-image: url("https://haowallpaper.com/link/common/file/previewFileImg/15758358777205056

dark"] #content,
[data-color-mode="dark"] #header,
[data-color-mode="dark"] #footer {
  background-color: var(--dark-content-bg) !important;
}

/* 文章列表卡片优化 */
.SideNav-item {
  background-color: rgba(255, 255, 255, 0.85) !important;
}
[data-color-mode="dark"] .SideNav-item {
  background-color: rgba(30, 41, 59, 0.85) !important;
}

/* 描述文本区优化 */
#content > div:first-child {
  background-color: rgba(241, 245, 249, 0.8) !important;
}
[data-color-mode="dark"] #content > div:first-child {
  background-color: rgba(30, 41, 59, 0.8) !important;
}
